      "number": 1,
      "arFull": "الٓرٰ ۫ كِتٰبٌ اَنْزَلْنٰهُ اِلَیْكَ لِتُخْرِجَ النَّاسَ مِنَ الظُّلُمٰتِ اِلَی النُّوْرِ ۙ۬ بِاِذْنِ رَبِّهِمْ اِلٰی صِرَاطِ الْعَزِیْزِ الْحَمِیْدِ ۟ۙ",
      "ur": "الرٰ! یہ عالی شان کتاب ہم نے آپ کی طرف اتاری ہے کہ آپ لوگوں کو اندھیروں سے اجالے کی طرف ﻻئیں[1] ، ان کے پروردگار کے حکم[2] سے، زبردست اور تعریفوں والے اللہ کی طرف.",
      "en": "Alif, Lām, Rā.[648] [This is] a Book which We have revealed to you, [O Muḥammad], that you might bring mankind out of darknesses into the light by permission of their Lord - to the path of the Exalted in Might, the Praiseworthy -",
      "footnotesUr": "[1] جس طرح دوسرے مقام پر بھی اللہ نے فرمایا '«هُوَ الَّذِيْ يُنَزِّلُ عَلٰي عَبْدِهٖٓ اٰيٰتٍۢ بَيِّنٰتٍ لِّيُخْرِجَكُمْ مِّنَ الظُّلُمٰتِ اِلَى النُّوْرِ»(سورہ الحدید:9) ۔« وہی ذات ہے جو اپنے بندے پر واضح آیات نازل فرماتی ہے تاکہ وہ تمہیں اندھیروں سے نکال کر نور کی طرف لائے »۔ «اَللّٰهُ وَلِيُّ الَّذِيْنَ اٰمَنُوْا ۙيُخْرِجُهُمْ مِّنَ الظُّلُمٰتِ اِلَى النُّوْرِ» ( البقرۃ:257)۔ ”اللہ ایمان داروں کا دوست ہے، وہ انہیں اندھیروں سے نکال کر نور کی طرف لاتا ہے“۔\n[2] یعنی پیغمبر کا کام ہدایت کا راستہ دکھانا ہے۔ لیکن اگر کوئی اس راستے کو اختیار کر لیتا ہے تو یہ صرف اللہ کے حکم اور مشیت سے ہوتا ہے کیونکہ اصل ہادی وہی ہے۔ اس کی مشیت اگر نہ ہو، تو پیغمبر کتنا بھی واعظ و نصیحت کر لے، لوگ ہدایت کا راستہ اپنانے کے لئے تیار نہیں ہوتے، جس کی متعدد مثالیں انبیائے سابقین میں موجود ہیں اور خود نبی (صلى الله عليه وسلم) باوجود شدید خواہش کے اپنے مہربان چچا ابو طالب کو مسلمان نہ کر سکے۔",
      "footnotesEn": "[648] See footnote to 2:1.",
