      "arFull": "لَّذِیْنَ یَسْتَحِبُّوْنَ الْحَیٰوةَ الدُّنْیَا عَلَی الْاٰخِرَةِ وَیَصُدُّوْنَ عَنْ سَبِیْلِ اللّٰهِ وَیَبْغُوْنَهَا عِوَجًا ؕ اُولٰٓىِٕكَ فِیْ ضَلٰلٍ بَعِیْدٍ ۟",
