      "arFull": "وَمَاۤ اَرْسَلْنَا مِنْ رَّسُوْلٍ اِلَّا بِلِسَانِ قَوْمِهٖ لِیُبَیِّنَ لَهُمْ ؕ فَیُضِلُّ اللّٰهُ مَنْ یَّشَآءُ وَیَهْدِیْ مَنْ یَّشَآءُ ؕ وَهُوَ الْعَزِیْزُ الْحَكِیْمُ ۟",
      "ur": "ہم نے ہر ہر نبی کو اس کی قومی زبان میں ہی بھیجا ہے تاکہ ان کے سامنے وضاحت سے بیان کر دے[1] ۔ اب اللہ جسے چاہے گمراه کر دے، اور جسے چاہے راه دکھا دے، وه غلبہ اور حکمت واﻻ ہے.[2]",
      "en": "And We did not send any messenger except [speaking] in the language of his people to state clearly for them, and Allāh sends astray [thereby] whom He wills[649] and guides whom He wills. And He is the Exalted in Might, the Wise.",
      "footnotesUr": "[1] پھر جب اللہ تعالٰی نے اہل دنیا پر یہ احسان فرمایا کہ ان کی ہدایت کے لئے کتابیں نازل کیں اور رسول بھیجے، تو اس احسان کی تکمیل اس طرح فرمائی کہ ہر رسول کو قومی زبان میں بھیجا تاکہ کسی کو ہدایت کا راستہ سمجھنے میں دقت نہ ہو۔\n[2] لیکن اس بیان و تشریح کے باوجود ہدایت اسے ملے گی جسے اللہ چاہے گا۔",
      "footnotesEn": "[649] i.e., those who refuse His guidance.",
