      "arTajweed": "أَلَمْ يَأْتِكُمْ نَبَؤُ<span class=\"tj-slnt\">ا۟</span> <span class=\"tj-ham-wasl\">ٱ</span>لَّذِينَ مِ<span class=\"tj-ikhafa\">ن قَ</span><span class=\"tj-qalaqah\">بْ</span>لِكُمْ قَوْمِ نُوح<span class=\"tj-idgham-ghunnah\">ٍ وَ</span>عَاد<span class=\"tj-idgham-ghunnah\">ٍ وَ</span>ثَمُودَ وَ<span class=\"tj-ham-wasl\">ٱ</span>لَّذِينَ مِن<span class=\"tj-iqlab\">ۢ ب</span>َعْدِهِمْ لَا يَعْلَمُهُمْ إِلَّا <span class=\"tj-ham-wasl\">ٱ</span>للَّهُ جَ<span class=\"tj-madda-obligatory\">آ</span>ءَتْهُمْ رُسُلُهُ<span class=\"tj-ikhafa-shafawi\">م بِ</span><span class=\"tj-ham-wasl\">ٱ</span>لْبَيِّنَ<span class=\"tj-madda-normal\">ٰ</span>تِ فَرَدُّ<span class=\"tj-madda-permissible\">وٓ</span><span class=\"tj-slnt\">ا۟</span> أَيْدِيَهُمْ فِ<span class=\"tj-madda-permissible\">ىٓ</span> أَفْوَ<span class=\"tj-madda-normal\">ٰ</span>هِهِمْ وَقَالُ<span class=\"tj-madda-permissible\">وٓ</span><span class=\"tj-slnt\">ا۟</span> إِ<span class=\"tj-ghunnah\">نَّ</span>ا كَفَرْنَا بِمَ<span class=\"tj-madda-permissible\">آ</span> أُرْسِلْتُ<span class=\"tj-ikhafa-shafawi\">م بِ</span>هِ<span class=\"tj-madda-normal\">ۦ</span> وَإِ<span class=\"tj-ghunnah\">نَّ</span>ا لَفِى شَكّ<span class=\"tj-idgham-ghunnah\">ٍ مِّ</span><span class=\"tj-ghunnah\">مَّ</span>ا تَ<span class=\"tj-qalaqah\">دْ</span>عُونَنَ<span class=\"tj-madda-permissible\">آ</span> إِلَيْهِ مُرِ<span class=\"tj-madda-permissible\">ي</span><span class=\"tj-qalaqah\">ب</span>ٍ"
