      "en": "Before him[653] is Hell, and he will be given a drink of purulent water.[654]",
      "footnotesUr": "[1] صَدِیْد، پیپ اور خون جو جہنمیوں کے گوشت اور ان کی کھالوں سے بہا ہوگا۔ بعض احادیث میں اسے عُصَارَةُ أَهْلِ النَّارِ (ﻣﺴﻨﺪ ﺍﺣﻤﺪ ﺟﻠﺪ ۔ ٥، ﺻﻔﺤﮧ ١٧١) (جہنمیوں کے جسم سے نچوڑا ہوا) اور بعض احادیث میں ہے یہ صدید اتنا گرم اور کھولتا ہوا ہوگا کہ ان کے منہ کے قریب پہنچتے ہی ان کے چہرے کی کھال جھلس کر گر پڑے گی اور اس کا ایک گھونٹ پیتے ہی ان کے پیٹ کی آنتیں پاخانے کے راستے باہر نکل پڑیں گی۔ أَعَاذَنَا اللهُ مِنْهُ",
