      "arTajweed": "وَمَا ذَ<span class=\"tj-madda-normal\">ٰ</span>لِكَ عَلَى <span class=\"tj-ham-wasl\">ٱ</span>للَّهِ بِعَزِ<span class=\"tj-madda-permissible\">ي</span>زٍ"
