      "arTajweed": "وَقَالَ <span class=\"tj-ham-wasl\">ٱ</span><span class=\"tj-laam-shamsiyah\">ل</span>شَّيْطَ<span class=\"tj-madda-normal\">ٰ</span>نُ لَ<span class=\"tj-ghunnah\">مَّ</span>ا قُضِىَ <span class=\"tj-ham-wasl\">ٱ</span>لْأَمْرُ إِ<span class=\"tj-ghunnah\">نَّ</span> <span class=\"tj-ham-wasl\">ٱ</span>للَّهَ وَعَدَكُمْ وَعْدَ <span class=\"tj-ham-wasl\">ٱ</span>لْحَقِّ وَوَعَ<span class=\"tj-idghaam_mutajanisayn\">د</span>تُّكُمْ فَأَخْلَفْتُكُمْ وَمَا كَانَ لِىَ عَلَيْكُ<span class=\"tj-idgham-shafawi\">م مِّ</span><span class=\"tj-ikhafa\">ن سُ</span>لْطَ<span class=\"tj-madda-normal\">ٰ</span>نٍ إِلَّ<span class=\"tj-madda-permissible\">آ</span> أَ<span class=\"tj-ikhafa\">ن دَ</span>عَوْتُكُمْ فَ<span class=\"tj-ham-wasl\">ٱ</span>سْتَجَ<span class=\"tj-qalaqah\">بْ</span>تُمْ لِى فَلَا تَلُومُونِى وَلُومُ<span class=\"tj-madda-permissible\">وٓ</span><span class=\"tj-slnt\">ا۟</span> أَ<span class=\"tj-ikhafa\">نفُ</span>سَكُ<span class=\"tj-idgham-shafawi\">م مَّ</span><span class=\"tj-madda-permissible\">آ</span> أَنَا۠ بِمُصْرِخِكُمْ وَمَ<span class=\"tj-madda-permissible\">آ</span> أَ<span class=\"tj-ikhafa\">نتُ</span><span class=\"tj-ikhafa-shafawi\">م بِ</span>مُصْرِخِىَّ إِ<span class=\"tj-ghunnah\">نِّ</span>ى كَفَرْتُ بِمَ<span class=\"tj-madda-permissible\">آ</span> أَشْرَكْتُمُونِ مِ<span class=\"tj-ikhafa\">ن قَ</span><span class=\"tj-qalaqah\">بْ</span>لُ إِ<span class=\"tj-ghunnah\">نَّ</span> <span class=\"tj-ham-wasl\">ٱ</span><span class=\"tj-laam-shamsiyah\">ل</span>ظَّ<span class=\"tj-madda-normal\">ٰ</span>لِمِينَ لَهُمْ عَذَابٌ أَلِ<span class=\"tj-madda-permissible\">ي</span>مٌ"
