      "arFull": "وَاُدْخِلَ الَّذِیْنَ اٰمَنُوْا وَعَمِلُوا الصّٰلِحٰتِ جَنّٰتٍ تَجْرِیْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِیْنَ فِیْهَا بِاِذْنِ رَبِّهِمْ ؕ تَحِیَّتُهُمْ فِیْهَا سَلٰمٌ ۟",
      "ur": "جو لوگ ایمان ﻻئے اور نیک عمل کیے وه ان جنتوں میں داخل کیے جائیں گے جن کے نیچے چشمے جاری ہیں جہاں انہیں ہمیشگی ہوگی اپنے رب کے حکم سے[1] ۔ جہاں ان کا خیر مقدم سلام سے ہوگا.[2]",
      "en": "And those who believed and did righteous deeds will be admitted to gardens beneath which rivers flow, abiding eternally therein by permission of their Lord; and their greeting therein will be, \"Peace!\"",
      "footnotesUr": "[1] یہ اہل شقاوت و اہل کفر کے مقابلے میں اہل سعادت اور اہل ایمان کا تذکرہ ہے۔ ان کا ذکر ان کے ساتھ اس لئے کیا گیا ہے تاکہ لوگوں کے اندر اہل ایمان والا کردار اپنانے کا شوق و رغبت پیدا ہو۔\n[2] یعنی آپس میں ان کا تحفہ ایک دوسرے کو سلام کرنا ہوگا۔ علاوہ ازیں فرشتے بھی ہر ہر دروازے سے داخل ہو ہو کر انہیں سلام عرض کریں گے۔",
