      "arFull": "وَمَثَلُ كَلِمَةٍ خَبِیْثَةٍ كَشَجَرَةٍ خَبِیْثَةِ جْتُثَّتْ مِنْ فَوْقِ الْاَرْضِ مَا لَهَا مِنْ قَرَارٍ ۟",
