      "arFull": "وَجَعَلُوْا لِلّٰهِ اَنْدَادًا لِّیُضِلُّوْا عَنْ سَبِیْلِهٖ ؕ قُلْ تَمَتَّعُوْا فَاِنَّ مَصِیْرَكُمْ اِلَی النَّارِ ۟",
