      "number": 36,
      "arFull": "رَبِّ اِنَّهُنَّ اَضْلَلْنَ كَثِیْرًا مِّنَ النَّاسِ ۚ فَمَنْ تَبِعَنِیْ فَاِنَّهٗ مِنِّیْ ۚ وَمَنْ عَصَانِیْ فَاِنَّكَ غَفُوْرٌ رَّحِیْمٌ ۟",
      "ur": "اے میرے پالنے والے معبود! انہوں نے بہت سے لوگوں کو راه سے بھٹکا دیا ہے[1] ۔ پس میری تابعداری کرنے واﻻ میرا ہے اور جو میری نافرمانی کرے تو تو بہت ہی معاف اور کرم کرنے واﻻ ہے.",
      "en": "My Lord, indeed they have led astray many among the people. So whoever follows me - then he is of me;[662] and whoever disobeys me - indeed, You are [yet] Forgiving and Merciful.",
      "footnotesUr": "[1] گمراہ کرنے کی نسبت ان پتھروں کی مورتیوں کی طرف جن کی مشرکین عبادت کرتے تھے، باوجود اس بات کے کہ وہ غیر عاقل ہیں، کیونکہ وہ گمراہی کا باعث تھیں اور ہیں۔",
      "footnotesEn": "[662] i.e., of my religion.",
