      "number": 46,
      "arFull": "وَقَدْ مَكَرُوْا مَكْرَهُمْ وَعِنْدَ اللّٰهِ مَكْرُهُمْ ؕ وَاِنْ كَانَ مَكْرُهُمْ لِتَزُوْلَ مِنْهُ الْجِبَالُ ۟",
      "ur": "یہ اپنی اپنی چالیں چل رہے ہیں اور اللہ کو ان کی تمام چالوں کا علم ہے[1] اور ان کی چالیں ایسی نہ تھیں کہ ان سے پہاڑ اپنی جگہ سے ٹل جائیں.[2]",
      "en": "And they had planned their plan, but with Allāh is [recorded] their plan, even if their plan had been [sufficient] to do away with the mountains.[665]",
      "footnotesUr": "[1] یہ جملہ حالیہ ہے کہ ہم نے ان کے ساتھ جو کیا وہ کیا، درآنحالیکہ انہوں نے باطل کے اثبات اور حق کے رد کرنے کے لئے مقدور بھر حیلے اور مکر کیے اور اللہ کو ان تمام چالوں کا علم ہے یعنی اس کے پاس درج ہے جس کی وہ ان کو سزا دے گا۔\n[2] کیونکہ اگر پہاڑ ٹل گئے ہوتے تو اپنی جگہ برقرار نہ ہوتے، جب کہ سب پہاڑ اپنی اپنی جگہ ثابت اور برقرار ہیں۔ یہ ان نافیہ کی صورت میں ہے دوسرے معین ان مخففۃ من المثقلۃ کے لیے گئے ہیں یعنی یقینا ان کے مکر تو اتنے بڑے تھے کہ پہاڑ بھی اپنی جگہ سے ٹل جاتے یہ تو اللہ تعالٰی ہی ہے جس نے ان کے مکروں کو کامیاب نہیں ہوتے دیا جیسے مشریکن کے شرک کے بارے میں اللہ تعالٰی نے فرمایا۔ «تَكَادُ السَّمَاوَاتُ يَتَفَطَّرْنَ مِنْهُ وَتَنْشَقُّ الأَرْضُ وَتَخِرُّ الْجِبَالُ هَدًّا (1) أَنْ دَعَوْا لِلرَّحْمَنِ وَلَدًا» (سورة مريم: 90-91)۔ ”قریب ہے کہ آسمان پھٹ پڑیں اور زمین شق ہو جائے اور پہاڑ ریزہ ریزہ ہو جائیں اس بات پر کہ انہوں نے کہا اللہ رحمٰن کی اولاد ہے“۔",
